def restore_json_sg(destination: Path, force: bool = False) -> Path:
    """Restaure le dossier json_SG dans <destination>/data/json_SG."""
    data_dir = destination / 'data'
    target = data_dir / 'json_SG'

    if target.exists():
        if not force:
            raise FileExistsError(
                f"Le dossier '{target}' existe deja. Relance avec --force pour l'ecraser."
            )
        shutil.rmtree(target)

    data_dir.mkdir(parents=True, exist_ok=True)

    archive_bytes = gzip.decompress(base64.b64decode(ARCHIVE_B64.encode('ascii')))
    with tarfile.open(fileobj=io.BytesIO(archive_bytes), mode='r:') as tar:
        try:
            tar.extractall(path=data_dir, filter='data')
        except TypeError:
            tar.extractall(path=data_dir)

    return target


def main() -> None:
    parser = argparse.ArgumentParser(
        description='Reconstruit data/json_SG a partir d une archive integree.'
    )
    parser.add_argument(
        '--destination',
        default='.',
        help='Dossier parent ou recreer data/json_SG (par defaut: repertoire courant).',
    )
    parser.add_argument(
        '--force',
        action='store_true',
        help='Ecrase data/json_SG s il existe deja.',
    )

    args = parser.parse_args()
    destination = Path(args.destination).expanduser().resolve()
    restored = restore_json_sg(destination=destination, force=args.force)
    print(f'Dossier recree: {restored}')


if __name__ == '__main__':
    main()
